162:     const dirY = moveY / len;
163:     const accel = player.acceleration * (keys.Shift ? 1.35 : 1);
164:     player.vx += dirX * accel * 0.016;
165:     player.vy += dirY * accel * 0.016;
166:     player.angle = Math.atan2(dirY, dirX);
167:   }
168: 
169:   const drag = player.friction * 0.016;
170:   const currentSpeed = Math.hypot(player.vx, player.vy);
171:   if (currentSpeed > 0) {
172:     const reduceX = (player.vx / currentSpeed) * drag;
173:     const reduceY = (player.vy / currentSpeed) * drag;
174:     player.vx -= reduceX;
175:     player.vy -= reduceY;
176:     if (Math.abs(player.vx) < 0.02) player.vx = 0;
177:     if (Math.abs(player.vy) < 0.02) player.vy = 0;
178:   }
179: 
180:   const maxSpeed = player.maxSpeed * (keys.Shift ? 1.2 : 1);
181:   const speed = Math.hypot(player.vx, player.vy);
182:   if (speed > maxSpeed) {
183:     const factor = maxSpeed / speed;
184:     player.vx *= factor;
185:     player.vy *= factor;
186:   }
187: 
188:   player.x += player.vx * 60;
189:   player.y += player.vy * 60;
190:   player.speed = Math.hypot(player.vx, player.vy) * 60;
