193: function collidesCircleRect(x, y, r, rect) {
194:   const closestX = clamp(x, rect.x, rect.x + rect.w);
195:   const closestY = clamp(y, rect.y, rect.y + rect.h);
196:   const dx = x - closestX;
197:   const dy = y - closestY;
198:   return dx * dx + dy * dy < r * r;
