293:       const my = cop.patrol.y - cop.y;
294:       cop.vx += (mx / (Math.hypot(mx, my) || 1)) * cop.speed * dt * 0.25;
295:       cop.vy += (my / (Math.hypot(mx, my) || 1)) * cop.speed * dt * 0.25;
