302:     const speedCap = chase ? 260 : 140;
303:     const current = Math.hypot(cop.vx, cop.vy);
304:     if (current > speedCap) {
305:       const ratio = speedCap / current;
306:       cop.vx *= ratio;
307:       cop.vy *= ratio;
308:     }
