310:     cop.x += cop.vx * 60 * dt;
311:     cop.y += cop.vy * 60 * dt;
312:     cop.x = clamp(cop.x, 20, WORLD.width - 20);
313:     cop.y = clamp(cop.y, 20, WORLD.height - 20);
314:     cop.vx *= 0.92;
315:     cop.vy *= 0.92;
316:   }
