function updatePolice(dt) {
  for (const cop of policeCars) {
    const dx = player.x - cop.x;
    const dy = player.y - cop.y;
    const dist = Math.hypot(dx, dy) || 1;
    const chase = dist < 550 || state.heat > 30;

    if (chase) {
      cop.vx += (dx / dist) * cop.speed * dt * 0.8;
      cop.vy += (dy / dist) * cop.speed * dt * 0.8;
      cop.angle = Math.atan2(cop.vy, cop.vx);
    } else {
      const mx = cop.patrol.x - cop.x;
      const my = cop.patrol.y - cop.y;
      cop.vx += (mx / (Math.hypot(mx, my) || 1)) * cop.speed * dt * 0.25;
      cop.vy += (my / (Math.hypot(mx, my) || 1)) * cop.speed * dt * 0.25;
      if (distance(cop, cop.patrol) < 40) {
        cop.patrol.x = 220 + Math.random() * (WORLD.width - 440);
        cop.patrol.y = 220 + Math.random() * (WORLD.height - 440);
      }
    }

    const speedCap = chase ? 260 : 140;
    const current = Math.hypot(cop.vx, cop.vy);
    if (current > speedCap) {
      const ratio = speedCap / current;
      cop.vx *= ratio;
      cop.vy *= ratio;
    }

    cop.x += cop.vx * 60 * dt;
    cop.y += cop.vy * 60 * dt;
    cop.x = clamp(cop.x, 20, WORLD.width - 20);
    cop.y = clamp(cop.y, 20, WORLD.height - 20);
    cop.vx *= 0.92;
    cop.vy *= 0.92;
  }
}

