284:     const chase = dist < 550 || state.heat > 30;
285:     let targetX;
286:     let targetY;
287:     let speedCap;
288: 
289:     if (chase) {
290:       targetX = dx / dist;
291:       targetY = dy / dist;
292:       speedCap = 260;
293:     } else {
294:       const mx = cop.patrol.x - cop.x;
295:       const my = cop.patrol.y - cop.y;
296:       const patrolDistance = Math.hypot(mx, my) || 1;
297:       targetX = mx / patrolDistance;
298:       targetY = my / patrolDistance;
299:       speedCap = 140;
300:       if (patrolDistance < 40) {
301:         cop.patrol.x = 220 + Math.random() * (WORLD.width - 440);
