307:     cop.vx += (targetX * speedCap - cop.vx) * turn;
308:     cop.vy += (targetY * speedCap - cop.vy) * turn;
309:     cop.angle = Math.atan2(cop.vy, cop.vx);
310:     cop.x += cop.vx * dt;
311:     cop.y += cop.vy * dt;
312:     cop.x = clamp(cop.x, 20, WORLD.width - 20);
