119:   margin-bottom: 4px;
120:   color: var(--accent);
121: }
122: 
123: #messageText {
124:   display: block;
125:   font-size: clamp(0.7rem, 1.6vw, 1rem);
126:   opacity: 0.9;
127: }
128: 
129: #minimapWrap {
130:   position: absolute;
131:   right: 20px;
132:   bottom: 20px;
133:   width: 190px;
134:   height: 190px;
135:   border: 1px solid rgba(134, 210, 255, 0.35);
136:   border-radius: 16px;
137:   background: rgba(8, 17, 23, 0.62);
138:   box-shadow: 0 12px 24px rgba(0, 0, 0, 0.25);
139:   padding: 8px;
140:   pointer-events: none;
141: }
142: 
143: #minimap {
144:   width: 100%;
145:   height: 100%;
146:   display: block;
147:   border-radius: 12px;
148:   background: rgba(10, 25, 27, 0.7);
149: }
150: 
151: #touchControls {
152:   position: absolute;
153:   left: 18px;
154:   bottom: 20px;
155:   display: flex;
156:   align-items: center;
157:   justify-content: space-between;
158:   width: min(42vw, 260px);
159:   gap: 10px;
160:   pointer-events: auto;
161: }
162: 
163: .leftCluster, .rightCluster {
164:   display: flex;
165:   gap: 10px;
166: }
167: 
168: button {
169:   width: 62px;
170:   height: 62px;
171:   border-radius: 18px;
172:   border: 1px solid rgba(138, 195, 255, 0.35);
173:   background: rgba(9, 18, 25, 0.72);
174:   color: var(--text);
175:   font-size: 1.8rem;
176:   box-shadow: 0 8px 18px rgba(0, 0, 0, 0.18);
177:   user-select: none;
178:   touch-action: manipulation;
179: }
180: 
181: button:active, button.active {
182:   background: rgba(89, 215, 255, 0.22);
183:   transform: translateY(1px) scale(0.98);
184: }
185: 
186: @media (max-width: 760px) {
187:   #topbar {
188:     flex-direction: column;
189:   }
190: 
191:   .stats {
192:     min-width: 0;
193:     justify-content: flex-start;
194:   }
195: 
196:   #messageBox {
197:     bottom: 150px;
198:   }
199: 
200:   #minimapWrap {
201:     width: 150px;
202:     height: 150px;
203:   }
204: }

